        var checkRow=one(db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND target_kind='CANDIDATE_SET' LIMIT 2 FOR UPDATE",original.tenantId(),original.projectId(),original.runId(),original.stepId()));var check=json.read(str(checkRow,"result_ref"));TaskCandidateAssemblyCheckService.validateReceipt(check);same(original.runId(),str(checkRow,"target_id"));same(report.artifactId(),str(checkRow,"target_revision"));same(original.inputSha256(),str(checkRow,"input_sha256"));same(report.artifactId(),str(checkRow,"coverage_artifact_id"));same(report.artifactId(),str(checkRow,"findings_artifact_id"));same(input.required("rule_revision").asText(),str(checkRow,"rule_manifest_id"));same(input.required("snapshot_id").asText(),str(checkRow,"scope_manifest_id"));same(input.required("candidates"),json.read(str(checkRow,"input_watermarks")));same(report.payload().required("blockers").isEmpty()?"SUCCEEDED":"WAITING_INPUT",str(checkRow,"status"));same(str(checkRow,"status"),check.required("status").asText());same(str(checkRow,"check_id"),check.required("check_id").asText());same(report.artifactId(),check.required("report_artifact_id").asText());same(report.reference().sha256(),check.required("report_sha256").asText());same(report.receiptSha256(),check.required("report_receipt_sha256").asText());same(original.inputSha256(),check.required("input_sha256").asText());if(check.required("document_saved").asBoolean()||check.required("n07_complete").asBoolean()||check.required("professional_approval").asBoolean())bad();journal(original,check,"task.candidate_assembly.check.committed");
