        var rule=one(db.queryForList("SELECT * FROM task_candidate_assembly_rule_set WHERE tenant_id=? AND revision_id=? LIMIT 2 FOR UPDATE",original.tenantId(),input.required("rule_revision").asText()));var rules=json.read(str(rule,"manifest_json"));same(input.required("rule_manifest_sha256").asText(),json.hash(rules));same(rules,json.read(str(checkRow,"rule_manifest")));registry(original,input.required("rule_revision").asText(),"CANDIDATE_ASSEMBLY_RULE_SET",json.hash(rules));journal(original,json.read(str(rule,"receipt_json")),"task.candidate_assembly.object.registered");
