    private ReadAuthority readAuthority(TaskCandidateAssemblyStageJournal.Original original,Set<String> artifacts)throws Exception{
        var run=one(db.queryForList("SELECT replay_manifest FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",original.tenantId(),original.projectId(),original.runId()));var replay=json.read(str(run,"replay_manifest"));same(original.input().required("replay_sha256").asText(),json.hash(replay));var policy=replay.required("execution_policy");var requirements=new LinkedHashMap<String,SourceReadProtocol.ReadRequirement>();var scopes=new HashSet<PermissionProtocol.Scope>();scopes.add(new PermissionProtocol.Scope(original.tenantId(),original.projectId(),"TASK",original.taskId()));scopes.add(new PermissionProtocol.Scope(original.tenantId(),original.projectId(),"PROJECT",original.projectId()));for(String artifact:artifacts)scopes.add(new PermissionProtocol.Scope(original.tenantId(),original.projectId(),"ARTIFACT",artifact));scopes.add(new PermissionProtocol.Scope(original.tenantId(),original.projectId(),"DOCUMENT",original.input().required("document_id").asText()));var external=original.input().path("cross_file_inputs").path("producer_selection").path("selection").path("documents");for(var d:external)scopes.add(new PermissionProtocol.Scope(original.tenantId(),original.projectId(),"DOCUMENT",d.required("document_id").asText()));
        for(var value:replay.required("scope_snapshot").required("members")){var m=new com.fasterxml.jackson.databind.ObjectMapper().treeToValue(value,TaskProtocol.ScopeSnapshotMember.class);var req=new SourceReadProtocol.ReadRequirement(m.source_version(),m.rights_revision(),original.projectId(),replay.required("snapshot_id").asText(),m.parse_version(),null,SourceReadProtocol.Use.FORMAL,policy.required("business_purpose").asText(),policy.required("environment").asText(),policy.required("region").asText(),null);if(requirements.put(req.sourceVersion(),req)!=null)bad();var row=one(sourceRows.source(req.sourceVersion()));scopes.add(new PermissionProtocol.Scope(original.tenantId(),row.ownerProjectId(),"SOURCE",row.sourceId()));}
        return new ReadAuthority(original,requirements,scopes,policy.required("business_purpose").asText());
    }
    /** Exact read-only exception for genuine original outputs and their selected sources.
     * Ordinary current owner/grant lookup still runs; no generic recovery scope grows. */
    public final class ReadAuthority {
        private final TaskCandidateAssemblyStageJournal.Original original;private final Map<String,SourceReadProtocol.ReadRequirement> requirements;private final Set<PermissionProtocol.Scope> scopes;private final String purpose;
        private ReadAuthority(TaskCandidateAssemblyStageJournal.Original original,Map<String,SourceReadProtocol.ReadRequirement> requirements,Set<PermissionProtocol.Scope> scopes,String purpose){this.original=original;this.requirements=Map.copyOf(requirements);this.scopes=Set.copyOf(scopes);this.purpose=purpose;}
        void requireResource(EnterpriseAccess.Admission a,PermissionProtocol.Scope scope,String action,String purpose)throws IOException{try{original.requireUnchanged();}catch(Exception e){throw new IOException(e);}if(a!=original.admission()||!this.purpose.equals(purpose)||!scopes.contains(scope)||!action.equals(switch(scope.resource_kind()){case "SOURCE"->"source.read";case "ARTIFACT"->"artifact.read";case "TASK"->"task.read";case "DOCUMENT"->"document.read";case "PROJECT"->"project.read";default->"FORBIDDEN";}))bad();}
        void requireRequirement(EnterpriseAccess.Admission a,SourceReadProtocol.ReadRequirement r)throws IOException{try{original.requireUnchanged();}catch(Exception e){throw new IOException(e);}if(a!=original.admission()||!r.equals(requirements.get(r.sourceVersion()))||r.use()!=SourceReadProtocol.Use.FORMAL)bad();}
        private void requireCurrent()throws Exception{for(var scope:scopes)grants.requireAssemblyOriginal(original.admission(),scope,switch(scope.resource_kind()){case "SOURCE"->"source.read";case "ARTIFACT"->"artifact.read";case "TASK"->"task.read";case "DOCUMENT"->"document.read";case "PROJECT"->"project.read";default->throw new IllegalArgumentException();},purpose,this);var rights=new HashMap<String,String>();for(var requirement:requirements.values()){var source=sources.requireAssemblyOriginal(original.admission(),requirement,this);rights.put(source.rights().rightsRevision(),source.source().sourceVersion());}
            for(var member:original.input().required("content_members")){String source=rights.get(member.required("rights_revision").asText());if(source==null)bad();var graph=lineage.inspect(member.required("upstream_version_id").asText(),limits.limits());if(!graph.reachableFrom(member.required("upstream_version_id").asText()).contains(source))bad();}original.requireUnchanged();}
    }
    private void registry(TaskCandidateAssemblyStageJournal.Original o,String id,String kind,String hash){var r=one(db.queryForList("SELECT content_sha256,owner_project_id,entity_kind FROM version_registry WHERE tenant_id=? AND version_id=? LIMIT 2",o.tenantId(),id));same(o.projectId(),str(r,"owner_project_id"));same(kind,str(r,"entity_kind"));same(hash,str(r,"content_sha256"));}
    private void journal(TaskCandidateAssemblyStageJournal.Original o,JsonNode receipt,String event)throws Exception{var a=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action=? AND result='SUCCESS' LIMIT 2",o.tenantId(),o.projectId(),receipt.required("audit_id").asText(),o.actorId(),event));var e=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND event_type=? LIMIT 2",o.tenantId(),receipt.required("event_id").asText(),event));same(receipt,json.read(str(a,"resource_ref")));same(receipt,json.read(str(e,"payload")));}
    private List<String> sorted(JsonNode array)throws Exception{if(!array.isArray())bad();var values=new TreeSet<String>();for(var value:array)if(!values.add(json.canonical(value)))bad();return List.copyOf(values);}
    private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static String str(Map<String,Object> r,String key){return Objects.requireNonNull(r.get(key)).toString();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
